preprocess.code:
const sql = args.sql.trim().replace(/;$/, "").trim();
// Conservative single-SELECT subset. The Superset connection must enforce read-only privileges.
if (!/^select\s/i.test(sql) || /[;\u0000\\]|--|\/\*|\*\/|\b(insert|update|delete|merge|create|drop|alter|truncate|replace|grant|revoke|call|set|use|load|unload|copy|into|lock|for\s+update)\b/i.test(sql)) {
  throw new Error("A single read-only SELECT is required");
}
const runAsync = args.runAsync === true;
return { ...request, headers: {}, variables: {
  databaseName: args.databaseName ?? "test_starrocks",
  sqlBody: JSON.stringify({ sql, runAsync, json: true }),
  ...(runAsync ? { asynchronous: "yes" } : {}),
} };

postprocess.code:
const payload = Array.isArray(response?.data) ? response : response?.result ?? response?.data ?? response;
const status = String(payload?.query?.status ?? payload?.status ?? "").toLowerCase();
const rows = Array.isArray(payload?.data) ? payload.data : payload?.rows;
if (["failed", "error", "stopped"].includes(status) || !Array.isArray(rows)) throw new Error("Missing SQL result");
const limit = 100;
const columns = Array.isArray(payload.columns)
  ? payload.columns.map(column => typeof column === "string" ? column : column?.name).filter(name => typeof name === "string")
  : [];
return { columns, rows: rows.slice(0, limit), rowCount: Math.min(rows.length, limit), truncated: rows.length > limit };
